import { TOKEN_NAME } from "../../../constants";
import Storage from "../../../utils/Storage";
const SERVER_URL = process.env.NODE_ENV === "production"
    ? process.env.SERVER_URL_PROD
    : process.env.SERVER_URL_DEV;
export async function createReceiptFromPhotoRequest(photo, shoppingListId) {
    const token = Storage.get(TOKEN_NAME);
    const formData = new FormData();
    formData.append("photo", photo);
    if (shoppingListId)
        formData.append("shoppingListId", shoppingListId);
    const response = await fetch(`${SERVER_URL}/api/create-receipt`, {
        method: "POST",
        body: formData,
        headers: {
            "Authorization": `Bearer ${token}`
        }
    });
    const body = await response.json().catch(() => ({}));
    if (!response.ok) {
        const error = new Error(typeof body.error === "string" ? body.error : "Receipt upload failed");
        error.status = response.status;
        throw error;
    }
    return body;
}
