import { MAX_RECEIPT_PHOTO_SIZE } from "../constants";
const SUPPORTED_IMAGE_TYPES = new Set(["image/jpeg", "image/png", "image/webp"]);
const SUPPORTED_IMAGE_EXTENSIONS = /\.(jpe?g|png|webp)$/i;
const HEIC_TYPES = new Set(["image/heic", "image/heif"]);
const HEIC_EXTENSIONS = /\.(heic|heif)$/i;
export class ReceiptPhotoError extends Error {
    code;
    constructor(code) {
        super(code);
        this.name = "ReceiptPhotoError";
        this.code = code;
    }
}
export function isLikelyHeic(file) {
    return HEIC_TYPES.has(file.type.toLowerCase()) || HEIC_EXTENSIONS.test(file.name);
}
export function isSupportedReceiptPhoto(file) {
    if (isLikelyHeic(file))
        return true;
    return SUPPORTED_IMAGE_TYPES.has(file.type.toLowerCase())
        || (!file.type && SUPPORTED_IMAGE_EXTENSIONS.test(file.name));
}
export async function prepareReceiptPhoto(file) {
    if (!file.size)
        throw new ReceiptPhotoError("empty");
    if (!isSupportedReceiptPhoto(file))
        throw new ReceiptPhotoError("unsupported");
    let preparedFile = file;
    if (isLikelyHeic(file)) {
        const { heicTo, isHeic } = await import("heic-to");
        if (!(await isHeic(file)))
            throw new ReceiptPhotoError("invalid-heic");
        const jpegBlob = await heicTo({
            blob: file,
            type: "image/jpeg",
            quality: 0.85
        });
        preparedFile = new File([jpegBlob], file.name.replace(HEIC_EXTENSIONS, ".jpg"), { type: "image/jpeg", lastModified: Date.now() });
    }
    if (preparedFile.size > MAX_RECEIPT_PHOTO_SIZE) {
        throw new ReceiptPhotoError("too-large");
    }
    return preparedFile;
}
export async function decodeReceiptPhoto(file) {
    if ("createImageBitmap" in window) {
        try {
            const bitmap = await createImageBitmap(file, { imageOrientation: "from-image" });
            const dimensions = { height: bitmap.height, width: bitmap.width };
            bitmap.close();
            if (!dimensions.width || !dimensions.height)
                throw new ReceiptPhotoError("undecodable");
            return dimensions;
        }
        catch {
            throw new ReceiptPhotoError("undecodable");
        }
    }
    const objectUrl = URL.createObjectURL(file);
    try {
        return await new Promise((resolve, reject) => {
            const image = new Image();
            image.onload = () => image.naturalWidth && image.naturalHeight
                ? resolve({ height: image.naturalHeight, width: image.naturalWidth })
                : reject(new ReceiptPhotoError("undecodable"));
            image.onerror = () => reject(new ReceiptPhotoError("undecodable"));
            image.src = objectUrl;
        });
    }
    finally {
        URL.revokeObjectURL(objectUrl);
    }
}
export function createCroppedReceiptFile(blob, originalName) {
    const baseName = originalName.replace(/\.[^.]+$/, "") || "receipt";
    return new File([blob], `${baseName}-cropped.jpg`, {
        type: "image/jpeg",
        lastModified: Date.now()
    });
}
