import { RECEIPT_PHOTO_ERROR_MESSAGE_IDS, UPLOAD_ERROR_MESSAGE_IDS } from "../constants";
import { ReceiptPhotoError } from "./receiptPhoto";
export function getErrorStatus(error) {
    return error?.status;
}
export function getReceiptPhotoErrorMessageId(error) {
    return error instanceof ReceiptPhotoError
        ? RECEIPT_PHOTO_ERROR_MESSAGE_IDS[error.code]
        : "addReceipt.validation.generic";
}
export function getUploadErrorMessageId(error) {
    const status = getErrorStatus(error);
    return status && UPLOAD_ERROR_MESSAGE_IDS[status]
        ? UPLOAD_ERROR_MESSAGE_IDS[status]
        : "addReceipt.error.network";
}
