import { CROPPED_PHOTO_QUALITY, CROP_ZOOM_MAX, CROP_ZOOM_MAX_SCALE_FACTOR, CROP_ZOOM_MIN, MAX_CROP_DIMENSION, MAX_RECEIPT_PHOTO_SIZE } from "../constants";
import { ReceiptPhotoError, createCroppedReceiptFile } from "./receiptPhoto";
export function getCropBaseZoom(cropper) {
    const canvasData = cropper.getCanvasData();
    const imageData = cropper.getImageData();
    const naturalWidth = canvasData.naturalWidth || imageData.naturalWidth;
    if (!canvasData.width || !naturalWidth)
        return null;
    return canvasData.width / naturalWidth;
}
export function clampCropZoom(zoom) {
    const boundedZoom = Math.min(CROP_ZOOM_MAX, Math.max(CROP_ZOOM_MIN, zoom));
    return Math.round(boundedZoom * 10) / 10;
}
export function getMinimumCropScale(cropper) {
    const canvasData = cropper.getCanvasData();
    const cropBoxData = cropper.getCropBoxData();
    const imageData = cropper.getImageData();
    const naturalWidth = canvasData.naturalWidth || imageData.naturalWidth;
    const naturalHeight = canvasData.naturalHeight || imageData.naturalHeight;
    if (!naturalWidth
        || !naturalHeight
        || !cropBoxData.width
        || !cropBoxData.height)
        return null;
    return Math.max(cropBoxData.width / naturalWidth, cropBoxData.height / naturalHeight);
}
export function getCropScaleRange(cropper, maximumScale) {
    const currentScale = getCropBaseZoom(cropper);
    const minimum = getMinimumCropScale(cropper);
    if (currentScale === null || minimum === null)
        return null;
    return {
        maximum: Math.max(maximumScale ?? currentScale * CROP_ZOOM_MAX_SCALE_FACTOR, currentScale, minimum),
        minimum
    };
}
export function hasValidCrop(cropper) {
    if (!cropper)
        return false;
    const data = cropper.getData();
    return data.width >= 1 && data.height >= 1;
}
export function getCropZoom(cropper, scaleRange) {
    const scale = getCropBaseZoom(cropper);
    const scaleDifference = scaleRange.maximum - scaleRange.minimum;
    if (scale === null || scaleDifference <= 0)
        return CROP_ZOOM_MIN;
    return clampCropZoom(CROP_ZOOM_MAX * (scale - scaleRange.minimum) / scaleDifference);
}
export function getCropScale(zoom, scaleRange) {
    const boundedZoom = clampCropZoom(zoom);
    return scaleRange.minimum
        + (scaleRange.maximum - scaleRange.minimum) * boundedZoom / CROP_ZOOM_MAX;
}
export function applyCropZoom(cropper, scaleRange, nextZoom) {
    const boundedZoom = clampCropZoom(nextZoom);
    if (!cropper || !scaleRange)
        return boundedZoom;
    cropper.zoomTo(getCropScale(boundedZoom, scaleRange));
    return getCropZoom(cropper, scaleRange);
}
export async function exportCroppedReceiptPhoto(cropper, sourceFile) {
    if (!cropper)
        throw new Error("Cropper is not ready");
    const canvas = cropper.getCroppedCanvas({
        fillColor: "#fff",
        imageSmoothingEnabled: true,
        imageSmoothingQuality: "high",
        maxHeight: MAX_CROP_DIMENSION,
        maxWidth: MAX_CROP_DIMENSION
    });
    if (!canvas?.width || !canvas.height)
        throw new Error("Crop export failed");
    const blob = await new Promise((resolve, reject) => {
        canvas.toBlob((result) => result ? resolve(result) : reject(new Error("Crop export failed")), "image/jpeg", CROPPED_PHOTO_QUALITY);
    });
    const file = createCroppedReceiptFile(blob, sourceFile.name);
    if (file.size > MAX_RECEIPT_PHOTO_SIZE)
        throw new ReceiptPhotoError("too-large");
    return file;
}
