export function createRestoredReceiptPhoto(draft) {
    return {
        preparedFile: new File([draft.preparedBlob], draft.preparedName, { lastModified: draft.updatedAt, type: draft.preparedBlob.type }),
        sourceFile: {
            lastModified: draft.originalLastModified,
            name: draft.originalName,
            size: draft.originalSize,
            type: draft.originalType
        }
    };
}
