import { useCallback } from "react";
import { useSearchParams } from "react-router-dom";
import { useShoppingListsQuery } from "../../../shopping-lists";
import { SHOPPING_LIST_ID_PARAM } from "../../constants";
function getShoppingListContextStatus({ hasCompletedItems, hasShoppingListId, isError, isPending, isRequested }) {
    if (!isRequested)
        return "none";
    if (!hasShoppingListId)
        return "unavailable";
    if (isPending)
        return "loading";
    if (isError)
        return "error";
    return hasCompletedItems ? "ready" : "unavailable";
}
export default function useReceiptShoppingListContext() {
    const [searchParams, setSearchParams] = useSearchParams();
    const isRequested = searchParams.has(SHOPPING_LIST_ID_PARAM);
    const shoppingListId = searchParams.get(SHOPPING_LIST_ID_PARAM)?.trim() || null;
    const { data: shoppingLists, isError, isPending, refetch } = useShoppingListsQuery(isRequested && Boolean(shoppingListId));
    const list = shoppingListId
        ? shoppingLists?.find((item) => item.id === shoppingListId)
        : undefined;
    const completedItemCount = list?.items.filter((item) => item.isCompleted).length || 0;
    const status = getShoppingListContextStatus({
        hasCompletedItems: Boolean(list && completedItemCount > 0),
        hasShoppingListId: Boolean(shoppingListId),
        isError,
        isPending,
        isRequested
    });
    const removeContext = useCallback(() => {
        setSearchParams((current) => {
            const next = new URLSearchParams(current);
            next.delete(SHOPPING_LIST_ID_PARAM);
            return next;
        }, { replace: true });
    }, [setSearchParams]);
    const retry = useCallback(() => {
        void refetch();
    }, [refetch]);
    return {
        backTo: status === "ready" && shoppingListId
            ? `/shopping-lists/${encodeURIComponent(shoppingListId)}`
            : "/",
        canSubmit: status === "none" || status === "ready",
        completedItemCount,
        listName: list?.name || null,
        removeContext,
        retry,
        shoppingListId,
        status
    };
}
