import { openDB } from "idb";
export const RECEIPT_DRAFT_DB_NAME = "receipt-vault-receipt-draft";
export const RECEIPT_DRAFT_STORE_NAME = "drafts";
export const RECEIPT_DRAFT_KEY = "current";
const RECEIPT_DRAFT_DB_VERSION = 1;
export class InvalidReceiptDraftError extends Error {
    constructor() {
        super("The stored receipt draft is invalid");
        this.name = "InvalidReceiptDraftError";
    }
}
function createDraftId() {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
        return crypto.randomUUID();
    }
    return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}
function isFiniteNumber(value) {
    return typeof value === "number" && Number.isFinite(value);
}
function isBlob(value) {
    if (!value || typeof value !== "object")
        return false;
    const blob = value;
    return Object.prototype.toString.call(value) === "[object Blob]"
        && isFiniteNumber(blob.size)
        && typeof blob.type === "string"
        && typeof blob.slice === "function";
}
function isReceiptDraft(value) {
    if (!value || typeof value !== "object")
        return false;
    const draft = value;
    return draft.schemaVersion === 1
        && typeof draft.draftId === "string"
        && draft.draftId.length > 0
        && isBlob(draft.preparedBlob)
        && draft.preparedBlob.size > 0
        && typeof draft.preparedName === "string"
        && typeof draft.originalName === "string"
        && isFiniteNumber(draft.originalSize)
        && typeof draft.originalType === "string"
        && isFiniteNumber(draft.originalLastModified)
        && isFiniteNumber(draft.createdAt)
        && isFiniteNumber(draft.updatedAt)
        && (draft.uploadState === "ready" || draft.uploadState === "attempted")
        && (draft.lastUploadAttemptAt === null || isFiniteNumber(draft.lastUploadAttemptAt));
}
async function openReceiptDraftDatabase() {
    return openDB(RECEIPT_DRAFT_DB_NAME, RECEIPT_DRAFT_DB_VERSION, {
        upgrade(database) {
            if (!database.objectStoreNames.contains(RECEIPT_DRAFT_STORE_NAME)) {
                database.createObjectStore(RECEIPT_DRAFT_STORE_NAME);
            }
        }
    });
}
async function withDatabase(operation) {
    const database = await openReceiptDraftDatabase();
    try {
        return await operation(database);
    }
    finally {
        database.close();
    }
}
export async function getReceiptDraft() {
    return withDatabase(async (database) => {
        const draft = await database.get(RECEIPT_DRAFT_STORE_NAME, RECEIPT_DRAFT_KEY);
        if (draft === undefined)
            return null;
        if (isReceiptDraft(draft))
            return draft;
        await database.delete(RECEIPT_DRAFT_STORE_NAME, RECEIPT_DRAFT_KEY);
        throw new InvalidReceiptDraftError();
    });
}
export async function saveReceiptDraft({ preparedFile, sourceFile }) {
    const now = Date.now();
    const draft = {
        schemaVersion: 1,
        draftId: createDraftId(),
        preparedBlob: preparedFile.slice(0, preparedFile.size, preparedFile.type),
        preparedName: preparedFile.name,
        originalName: sourceFile.name,
        originalSize: sourceFile.size,
        originalType: sourceFile.type,
        originalLastModified: sourceFile.lastModified,
        createdAt: now,
        updatedAt: now,
        uploadState: "ready",
        lastUploadAttemptAt: null
    };
    await withDatabase(async (database) => {
        await database.put(RECEIPT_DRAFT_STORE_NAME, draft, RECEIPT_DRAFT_KEY);
    });
    return draft;
}
async function updateReceiptDraft(draftId, update) {
    return withDatabase(async (database) => {
        const transaction = database.transaction(RECEIPT_DRAFT_STORE_NAME, "readwrite");
        const draft = await transaction.store.get(RECEIPT_DRAFT_KEY);
        if (!draft || !isReceiptDraft(draft) || draft.draftId !== draftId) {
            await transaction.done;
            return null;
        }
        const updatedDraft = update(draft);
        await transaction.store.put(updatedDraft, RECEIPT_DRAFT_KEY);
        await transaction.done;
        return updatedDraft;
    });
}
export function markReceiptDraftAttempted(draftId) {
    const now = Date.now();
    return updateReceiptDraft(draftId, (draft) => ({
        ...draft,
        lastUploadAttemptAt: now,
        updatedAt: now,
        uploadState: "attempted"
    }));
}
export function markReceiptDraftReady(draftId) {
    return updateReceiptDraft(draftId, (draft) => ({
        ...draft,
        updatedAt: Date.now(),
        uploadState: "ready"
    }));
}
export async function deleteReceiptDraft(draftId) {
    return withDatabase(async (database) => {
        const transaction = database.transaction(RECEIPT_DRAFT_STORE_NAME, "readwrite");
        const draft = await transaction.store.get(RECEIPT_DRAFT_KEY);
        if (!draft || draft.draftId !== draftId) {
            await transaction.done;
            return false;
        }
        await transaction.store.delete(RECEIPT_DRAFT_KEY);
        await transaction.done;
        return true;
    });
}
