import { format, isValid, parse, parseISO } from "date-fns";
import { formatInTimeZone } from "date-fns-tz";
import { SHOPPING_LIST_ID_PARAM } from "../constants";
const DATE_PARAM_FORMAT = "yyyy-MM-dd";
const DATE_PARSE_REFERENCE = new Date(0);
function isValidDateParam(value) {
    if (!value)
        return false;
    const parsedDate = parse(value, DATE_PARAM_FORMAT, DATE_PARSE_REFERENCE);
    return isValid(parsedDate) && format(parsedDate, DATE_PARAM_FORMAT) === value;
}
function getReceiptDateParam(receiptDate) {
    if (isValidDateParam(receiptDate))
        return receiptDate;
    const parsedDate = parseISO(receiptDate);
    return isValid(parsedDate)
        ? formatInTimeZone(parsedDate, "UTC", DATE_PARAM_FORMAT)
        : null;
}
export function getReceiptDetailSearch(currentSearch, receiptDate) {
    const searchParams = new URLSearchParams(currentSearch);
    searchParams.delete(SHOPPING_LIST_ID_PARAM);
    const dateParam = getReceiptDateParam(receiptDate);
    if (!dateParam) {
        const nextSearch = searchParams.toString();
        return nextSearch ? `?${nextSearch}` : "";
    }
    const startDate = searchParams.get("startDate");
    const endDate = searchParams.get("endDate");
    let didChangeRange = false;
    if (!isValidDateParam(startDate) || dateParam < startDate) {
        searchParams.set("startDate", dateParam);
        didChangeRange = true;
    }
    if (!isValidDateParam(endDate) || dateParam > endDate) {
        searchParams.set("endDate", dateParam);
        didChangeRange = true;
    }
    if (didChangeRange)
        searchParams.delete("byCreatedDate");
    const nextSearch = searchParams.toString();
    return nextSearch ? `?${nextSearch}` : "";
}
