import { useCallback, useRef, useState } from "react";
import { deleteReceiptDraft, markReceiptDraftAttempted, markReceiptDraftReady, saveReceiptDraft } from "../../persistence/receiptDraftStore";
import { createRestoredReceiptPhoto } from "../../utils/receiptDraft";
import useReceiptDraftPreviewUrl from "./useReceiptDraftPreviewUrl";
import useReceiptDraftRestoration from "./useReceiptDraftRestoration";
function useReceiptDraftPersistence() {
    const [draft, setDraft] = useState(null);
    const [isRecoveryPending, setIsRecoveryPending] = useState(false);
    const [persistenceWarning, setPersistenceWarning] = useState(null);
    const draftRef = useRef(null);
    const pendingSaveRef = useRef(null);
    const updateDraft = useCallback((nextDraft) => {
        draftRef.current = nextDraft;
        setDraft(nextDraft);
    }, []);
    const restoreDraft = useCallback((restoredDraft) => {
        updateDraft(restoredDraft);
        setIsRecoveryPending(Boolean(restoredDraft));
    }, [updateDraft]);
    const handleRestorationError = useCallback((warning) => {
        setPersistenceWarning(warning);
    }, []);
    const isRestoring = useReceiptDraftRestoration({
        onError: handleRestorationError,
        onRestore: restoreDraft
    });
    const previewUrl = useReceiptDraftPreviewUrl(draft && isRecoveryPending ? draft.preparedBlob : null);
    const dismissPersistenceWarning = useCallback(() => setPersistenceWarning(null), []);
    const persistPhoto = useCallback(async ({ preparedFile, sourceFile }) => {
        setIsRecoveryPending(false);
        const previousSave = pendingSaveRef.current ?? Promise.resolve(null);
        const pendingSave = previousSave
            .then(() => saveReceiptDraft({ preparedFile, sourceFile }))
            .then((nextDraft) => {
            updateDraft(nextDraft);
            return nextDraft;
        })
            .catch(() => {
            updateDraft(null);
            setPersistenceWarning("save");
            return null;
        });
        pendingSaveRef.current = pendingSave;
        const savedDraft = await pendingSave;
        if (pendingSaveRef.current === pendingSave)
            pendingSaveRef.current = null;
        return savedDraft;
    }, [updateDraft]);
    const continueDraft = useCallback(() => {
        const currentDraft = draftRef.current;
        if (!currentDraft)
            return null;
        setIsRecoveryPending(false);
        return createRestoredReceiptPhoto(currentDraft);
    }, []);
    const discardDraft = useCallback(async () => {
        await pendingSaveRef.current;
        const currentDraft = draftRef.current;
        if (!currentDraft) {
            setIsRecoveryPending(false);
            return true;
        }
        try {
            await deleteReceiptDraft(currentDraft.draftId);
            updateDraft(null);
            setIsRecoveryPending(false);
            return true;
        }
        catch {
            setPersistenceWarning("discard");
            return false;
        }
    }, [updateDraft]);
    const markUploadAttempted = useCallback(async () => {
        const currentDraft = draftRef.current;
        if (!currentDraft)
            return;
        try {
            const updatedDraft = await markReceiptDraftAttempted(currentDraft.draftId);
            if (updatedDraft)
                updateDraft(updatedDraft);
        }
        catch {
            setPersistenceWarning("update");
        }
    }, [updateDraft]);
    const markUploadReady = useCallback(async () => {
        const currentDraft = draftRef.current;
        if (!currentDraft)
            return;
        try {
            const updatedDraft = await markReceiptDraftReady(currentDraft.draftId);
            if (updatedDraft)
                updateDraft(updatedDraft);
        }
        catch {
            setPersistenceWarning("update");
        }
    }, [updateDraft]);
    const deleteDraftAfterSuccess = useCallback(async () => {
        const currentDraft = draftRef.current;
        if (!currentDraft)
            return;
        try {
            await deleteReceiptDraft(currentDraft.draftId);
        }
        catch {
            try {
                await deleteReceiptDraft(currentDraft.draftId);
            }
            catch {
                setPersistenceWarning("cleanup");
            }
        }
        finally {
            updateDraft(null);
            setIsRecoveryPending(false);
        }
    }, [updateDraft]);
    return {
        continueDraft,
        deleteDraftAfterSuccess,
        discardDraft,
        dismissPersistenceWarning,
        draft,
        isRecoveryPending,
        isRestoring,
        markUploadAttempted,
        markUploadReady,
        persistPhoto,
        persistenceWarning,
        previewUrl
    };
}
export default useReceiptDraftPersistence;
